-- Magnanimous Store sourcing queue: minimum 15 product targets per category.
-- These are sourcing targets, not claims that a supplier mapping is already verified.
CREATE TABLE IF NOT EXISTS store_sourcing_targets (
  id TEXT PRIMARY KEY,
  category_slug TEXT NOT NULL,
  product_name TEXT NOT NULL,
  search_query TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'queued',
  supplier_provider TEXT NOT NULL DEFAULT 'cj',
  matched_product_id TEXT NOT NULL DEFAULT '',
  matched_product_sku TEXT NOT NULL DEFAULT '',
  matched_title TEXT NOT NULL DEFAULT '',
  matched_price_cents INTEGER,
  match_score REAL,
  last_error TEXT NOT NULL DEFAULT '',
  last_searched_at INTEGER,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE(category_slug,product_name)
);
CREATE INDEX IF NOT EXISTS idx_store_sourcing_targets_status ON store_sourcing_targets(status,category_slug,updated_at);

